const job = $input.first().json;
const summary = job.summary || {};
const ts = new Date(job.finished_at || new Date()).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', dateStyle: 'medium', timeStyle: 'short' });

let body = `Facebook Groups Like Report\n`;
body += `Completed: ${ts} IST\n`;
body += `Status: ${job.status}\n`;
body += `Reaction: ${job.reaction || 'Like'}\n`;
body += `Total posts liked: ${summary.total_posts_liked || 0}\n`;
body += `Total comments liked: ${summary.total_comments_liked || 0}\n`;
body += `Groups done: ${summary.done || 0}  failed: ${summary.failed || 0}  skipped: ${summary.skipped || 0}\n`;
body += `\n${'─'.repeat(60)}\n\n`;

for (const r of (job.results || [])) {
  body += `GROUP: ${r.group}\n`;
  body += `  Status : ${r.status}${r.error ? ' – ' + r.error : ''}\n`;
  if (r.status === 'done') {
    body += `  Posts liked    : ${r.posts_liked || 0}\n`;
    body += `  Comments liked : ${r.comments_liked || 0}\n`;
    body += `  Buttons found  : ${r.buttons_found ?? 'n/a'}\n`;
    if (r.liked_posts && r.liked_posts.length > 0) {
      body += `  Liked posts:\n`;
      for (const p of r.liked_posts) {
        body += `    • ${p.author || 'Unknown author'}\n`;
        if (p.post_text) body += `      "${p.post_text.slice(0, 100)}"\n`;
        if (p.post_url)  body += `      ${p.post_url}\n`;
        body += `      Liked at: ${new Date(p.liked_at).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' })} IST\n`;
        if (p.comments_liked) body += `      Comments liked: ${p.comments_liked}\n`;
      }
    } else {
      body += `  (no post detail captured)\n`;
    }
  }
  body += `\n`;
}

return [{ json: { status: job.status, total_posts_liked: summary.total_posts_liked || 0, email_body: body, results: job.results } }];
